sys_script_include.script:
var InfoArchiveRecords = Class.create();
InfoArchiveRecords.prototype = {

    initialize: function() {},

    CustodyTradeArchivetradetable: function(sysid) {
        var xml = '';

        try {
            if (!sysid) {
                gs.info('No sys_id provided');
            }

            //Query the archive Custody Trade table
            var trade_gr = new GlideRecord('ar_x_hsb11_mss_c_proc_mss_custody_trade');
            trade_gr.addQuery('sys_id', sysid);
            trade_gr.query();
            if (trade_gr.next()) {

                //Array of field names
                var fields = [
                    'counterparty_code', 'counterparty_reference', 'instruction_source', 'customer_reference', 'owning_business', 'security_name', 'settlement_amount_currency', 'enitity_code', 'legacy_status', 'actual_settlement_date', 'trade_id', 'transaction_type', 'value_date', 'security_id', 'settlement_quantity', 'counterparty_name', 'amount_settled', 'settlement_amount', 'settlement_date', 'isin', 'location_code', 'mis_group', 'transaction_reference', 'securities_account', 'trade_date', 'sys_id'
                ];
                xml += '<CUSTODY_TRADE xmlns="urn:eas-hsbc:xsd:iqube:custody_trade:1.0">';

                var i = 0;
                while (i < fields.length) {
                    var fieldName = fields[i];
                    var fieldValue = trade_gr.getValue(fieldName);

                    // Processing only non-null values
                    if (fieldValue) {
                        var fieldElement = trade_gr.getElement(fieldName);
                        var fieldType = fieldElement.getED().getInternalType();
                        // gs.info('Field type: ' + fieldType + ', Field value of ' + fieldName + ' is: ' + fieldValue); // -->test 

                        xml += '<' + fieldName + '>';

                        // Handling Date/DateTime fields using formatDateTime()
                        if (fieldType == 'glide_date' || fieldType == 'glide_date_time') {
                            xml += this.formatDateTime(fieldValue);
                        } else {
                            xml += fieldValue;
                        }
                        xml += '</' + fieldName + '>';
                    }
                    i++;
                }

                xml += '</CUSTODY_TRADE>';

            } else {
                gs.info('No archive record found for sysid: ' + sysid);
            }
        } catch (e) {
            gs.error('InfoArchiveRecords: Error Message : ' + e.message);
        }
        return xml;
    },

    formatDateTime: function(dateValue) {

        if (!dateValue) {
            return null;
        }
        var parts = dateValue.split(" ");
        var date_part = parts[0];
        var time_part = parts[1];
        //If Date field type
        if (!time_part) {
            return date_part + "T00:00:00Z";
        }
        //If DateTime field type
        var gt = new GlideDateTime(dateValue);
        var date = gt.getDate().getValue();
        var time = gt.getTime().getByFormat('HH:mm:ss');

        return date + "T" + time + "Z";

    },


    CustodyAuditArchivetradetable: function(sysid) {
        var xml = '';

        try {
            if (!sysid) {
                gs.info('No sysid provided');
            }

            //Query the Sys Audit table
            var audit_gr = new GlideRecord('sys_audit');
            audit_gr.addQuery('sys_id', sysid);
            audit_gr.query();
            if (audit_gr.next()) {

                //Get the field values from table

                var sys_created_on = this.formatDateTime(audit_gr.getValue('sys_created_on'));
                var tablename = audit_gr.getValue('tablename');
                var fieldname = audit_gr.getValue('fieldname');
                var documentkey = audit_gr.getValue('documentkey');
                var user = audit_gr.getValue('user');
                var oldvalue = audit_gr.getValue('oldvalue');
                var newvalue = audit_gr.getValue('newvalue');

                //Constructing XML
                xml =
                    '<CUSTODY_AUDIT xmlns = "urn:eas-hsbc:xsd:iqube:custody_audit:1.0">' +
                    '<sys_created_on>' + sys_created_on + '</sys_created_on>' +
                    '<tablename>' + tablename + '</tablename>' +
                    '<fieldname>' + fieldname + '</fieldname>' +
                    '<documentkey>' + documentkey + '</documentkey>' +
                    '<user>' + user + '</user>' +
                    '<oldvalue>' + oldvalue + '</oldvalue>' +
                    '<newvalue>' + newvalue + '</newvalue>' +
                    '</CUSTODY_AUDIT>';
            } else {
                gs.info('No record found for sysid: ' + sysid);
            }
        } catch (e) {
            gs.error('InfoArchiveRecords: Error Message : ' + e.message);
        }
        return xml;
    },



    ArchiveCustodyTasktable: function(sysid) {
        var xml = '';

        try {
            if (!sysid) {
                gs.info('No sys_id provided');
            }

            //Query the archive Custody Task table
            var task_gr = new GlideRecord('ar_x_hsb11_mss_c_proc_mss_custody_task');
            task_gr.addQuery('sys_id', sysid);
            task_gr.query();
            if (task_gr.next()) {

                var fields = [
                    'active', 'advice', 'amend_checker_decision', 'assigned_to', 'assignment_group', 'auto_resume_indicator', 'bk_to_bk_info', 'bulk_id', 'cancel_by', 'cancellation_reference', 'closed_at', 'closed_by', 'collect_cancel_charge', 'corresponding_switch_trade_advice', 'corresponding_switch_trade_id', 'corresponding_switch_trade_suspend', 'decision', 'decision_reason', 'description', 'due_date', 'due_date_status', 'follow_up', 'fxr_td', 'ghss_trade_ref_id', 'lock', 'locktime', 'maker_assignment_group', 'new_maker_task_assignee', 'number', 'opened_at', 'opened_by', 'outcome', 'position_attribute_sync', 'position_data_refresh_frequency_in_seconds', 'priority', 'reason_code', 'reason_description', 'reassignment_count', 'refresh_form', 'settlement_date', 'settlement_type', 'short_description', 'state', 'sub_trade_task_type', 'suspend', 'swift_attribute_sync', 'swift_linking_reference', 'swift_linking_reference_id', 'swift_linking_reference_id_ref', 'sys_created_by', 'sys_created_on', 'sys_domain', 'sys_domain_path', 'sys_id', 'sys_mod_count', 'sys_updated_by', 'sys_updated_on', 'task_effective_number', 'trade_case_id', 'trade_id', 'trade_task_template_id', 'trade_task_type', 'tran_reference_for_swift_linking', 'value_date'
                ];
                xml += '<CUSTODY_TASK xmlns="urn:eas-hsbc:xsd:iqube:custody_task:1.0">';

                var i = 0;
                while (i < fields.length) {
                    var fieldName = fields[i];
                    // var fieldValue = task_gr.getValue(fieldName);
                    var fieldValue = task_gr.getDisplayValue(fieldName);

                    // Processing only non-null values
                    if (fieldValue) {
                        var fieldElement = task_gr.getElement(fieldName);
                        var fieldType = fieldElement.getED().getInternalType();
                        // gs.info('Field type: ' + fieldType + ', Field value of ' + fieldName + ' is: ' + fieldValue); // -->test 

                        xml += '<' + fieldName + '>';

                        // Handling Date/DateTime fields using formatDateTime()
                        if (fieldType == 'glide_date' || fieldType == 'glide_date_time') {
                            xml += this.formatDateTime(fieldValue);
                        } else {
                            xml += fieldValue;
                        }
                        xml += '</' + fieldName + '>';
                    }
                    i++;
                }

                xml += '</CUSTODY_TASK>';

            } else {
                gs.info('No archive record found for sysid: ' + sysid);
            }
        } catch (e) {
            gs.error('InfoArchiveRecords: Error Message : ' + e.message);
        }
        return xml;
    },


    ArchiveCustodySwiftMessagestable: function(sysid) {
        var xml = '';

        try {
            if (!sysid) {
                gs.info('No sys_id provided');
            }

            //Query the archive Custody Swift Messages table
            var swift_gr = new GlideRecord('ar_x_hsb11_mss_c_swft_mss_custody_swift_messages');
            swift_gr.addQuery('sys_id', sysid);
            swift_gr.query();
            if (swift_gr.next()) {

                //Array of field names
                var fields = [
                    'message_source_id', 'message_format', 'message_function_type', 'trade_id', 'message_source_timestamp', 'message_status', 'sender_id', 'owning_business', 'message_channel', 'message_source_system', 'sys_created_on', 'sys_created_by', 'exception_message_text', 'message_content', 'sys_updated_on', 'sys_updated_by', 'sys_mod_count', 'sys_id'
                ];
                xml += '<CUSTODY_SWIFT xmlns="urn:eas-hsbc:xsd:iqube:custody_swift:1.0">';

                var i = 0;
                while (i < fields.length) {
                    var fieldName = fields[i];
                    var fieldValue = swift_gr.getValue(fieldName);

                    // Apply fallback logic: Use Trade Base value when Trade ID is missing
                    if (fieldName == 'trade_id') {
                        var tradeID = (swift_gr.getValue('trade_id') || '').trim();
                        var tradeBase = (swift_gr.getValue('trade_base') || '').trim();
                        var finaltradeID = (tradeID !== '' ? tradeID : tradeBase);
                        xml += '<trade_id>' + finaltradeID + '</trade_id>';
                        i++;
                        continue;
                    }

                    // Processing only non-null values
                    if (fieldValue) {
                        var fieldElement = swift_gr.getElement(fieldName);
                        var fieldType = fieldElement.getED().getInternalType();
                        // gs.info('Field type: ' + fieldType + ', Field value of ' + fieldName + ' is: ' + fieldValue); // -->test 

                        xml += '<' + fieldName + '>';

                        // Handling Date/DateTime fields using formatDateTime()
                        if (fieldType == 'glide_date' || fieldType == 'glide_date_time') {
                            xml += this.formatDateTime(fieldValue);
                        } else {
                            xml += fieldValue;
                        }
                        xml += '</' + fieldName + '>';
                    }
                    i++;
                }

                xml += '</CUSTODY_SWIFT>';

            } else {
                gs.info('No archive record found for sysid: ' + sysid);
            }
        } catch (e) {
            gs.error('InfoArchiveRecords: Error Message : ' + e.message);
        }
        return xml;
    },

