            case_gr.addQuery('sys_id', sysid);
            case_gr.query();
            if (case_gr.next()) {

                //Array of field names

                var fields = [
                    'active', 'amend_case', 'bulk_id', 'case_report', 'case_status', 'closed_at', 'closed_by', 'current_checker_assignee', 'current_maker_assignee', 'description', 'due_date', 'number', 'opened_at', 'opened_by', 'reinitiate_process', 'resolved_at', 'resolved_by', 'short_description', 'state', 'sys_created_by', 'sys_created_on', 'sys_id', 'sys_mod_count', 'sys_updated_by', 'sys_updated_on', 'task_effective_number', 'trade_id', 'triggered_by', 'u_fo_process_status', 'u_objectidtype', 'u_source'
                ];
                xml += '<CUSTODY_CASE xmlns="urn:eas-hsbc:xsd:iqube:custody_case:1.0">';

                var i = 0;
                while (i < fields.length) {
                    var fieldName = fields[i];
                    var fieldValue = case_gr.getValue(fieldName);

                    // Processing only non-null values
                    if (fieldValue) {
                        var fieldElement = case_gr.getElement(fieldName);
                        var fieldType = fieldElement.getED().getInternalType();
                        // gs.info('Field type: ' + fieldType + ', Field value of ' + fieldName + ' is: ' + fieldValue); // -->test 

                        xml += '<' + fieldName + '>';

                        // Handling Date/DateTime fields using formatDateTime()
                        if (fieldType == 'glide_date' || fieldType == 'glide_date_time') {
                            xml += this.formatDateTime(fieldValue);
                        } else {
                            xml += fieldValue;
                        }
                        xml += '</' + fieldName + '>';
                    }
                    i++;
                }

                xml += '</CUSTODY_CASE>';

            } else {
                gs.info('No archive record found for sysid: ' + sysid);
            }
        } catch (e) {
            gs.error('InfoArchiveRecords: Error Message : ' + e.message);
        }
        return xml;
    },


    ArchiveCustodyJournalFieldtable: function(sysid) {
        var xml = '';

        try {
            if (!sysid) {
                gs.info('No sys_id provided');
            }

            //Query the Sys Journal table
            var journal_gr = new GlideRecord('sys_journal_field');
            journal_gr.addQuery('sys_id', sysid);
            journal_gr.query();
            if (journal_gr.next()) {

                var name = journal_gr.getValue('name');
                var element = journal_gr.getValue('element');
                var element_id = journal_gr.getValue('element_id');
                var value = journal_gr.getValue('value');
                var sys_created_on = this.formatDateTime(journal_gr.getValue('sys_created_on'));
                var sys_created_by = journal_gr.getValue('sys_created_by');

                //Constructing XML
                xml =
                    '<CUSTODY_JOURNAL xmlns = "urn:eas-hsbc:xsd:iqube:custody_journal:1.0">' +
                    '<name>' + name + '</name>' +
                    '<element>' + element + '</element>' +
                    '<element_id>' + element_id + '</element_id>' +
                    '<value>' + value + '</value>' +
                    '<sys_created_on>' + sys_created_on + '</sys_created_on>' +
                    '<sys_created_by>' + sys_created_by + '</sys_created_by>' +
                    '</CUSTODY_JOURNAL>';
            } else {
                gs.info('No record found for sysid: ' + sysid);
            }
        } catch (e) {
            gs.error('InfoArchiveRecords: Error Message : ' + e.message);
        }
        return xml;
    },

    type: 'InfoArchiveRecords'
};
